import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import CountryList from "@/JsonFiles/CountryList.json";
import { create_list_edit_delete_asset_retailers } from "@/graphql/mutations.js";
import { create_list_edit_delete_asset_distributors } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    createretailer: Boolean
  },
  data() {
    return {
      loading: false,
      retailerName: "",
      retailereCode: "",
      retaileremailID: "",
      countryList: "",
      Distributor: "",
      contactNumber: "",
      contactName: "",
      Distributoritems: [],
      countryitems: [],
      rules: {
        required: value => !!value || "Required.",
        email: value => {
          if (value === "" || value === null) {
            return true;
          }
          const pattern = /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
          return pattern.test(value) || "Invalid Email";
        },
        phoneNumber: value => {
          return value && /^[0-9]{8,13}$/.test(value) || "Length must be between 8 and 13 digits";
        }
      }
    };
  },
  watch: {
    createretailer: {
      async handler() {
        await this.fetch_details();
        await this.fetch_distributorlist();
      },
      immediate: true
    }
  },
  methods: {
    async fetch_distributorlist() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_asset_distributors, {
          input: {
            organization_id: data.organization.organization_id,
            action_type: "LIST"
          }
        }));
        var response = JSON.parse(result.data.create_list_edit_delete_asset_distributors);
        this.Distributoritems = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          var datadistributor = response.data;
          datadistributor.forEach(element => {
            this.Distributoritems.push({
              name: element.asset_distributor_name,
              value: element.asset_distributor_id
            });
          });
          //   this.Distributoritems = response.data;
          this.tableLoading = false;
        } else {
          this.Distributoritems = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.distributorRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    fetch_details() {
      CountryList.forEach(element => {
        this.countryitems.push({
          title: element.name + "(" + element.dial_code + ")",
          code: element.dial_code
        });
      });
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form.resetValidation();
      this.$refs.form.reset();
    },
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_asset_retailers, {
          input: {
            action_type: "CREATE",
            organization_id: data.organization.organization_id,
            asset_retailer_name: this.retailerName,
            asset_retailer_email: this.retaileremailID == null ? "" : this.retaileremailID,
            county_code: this.countryList == null ? "" : this.countryList,
            contact_number: this.contactNumber == null ? "" : this.contactNumber,
            asset_distributor_id: this.Distributor,
            asset_retailer_code: this.retailereCode,
            contact_name: this.contactName == null ? "" : this.contactName
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_edit_delete_asset_retailers);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.resetValidation();
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
